const hooks = currentComponent.__hooks;
if (hooks) {
	if (previousComponent === currentComponent) {
		// The component re-rendered itself within the same render loop
		// (e.g. a state setter was called during render). Any render in
		// between is disposed: drop the effects it scheduled and restore
		// every non-state hook to the value it had when the previous
		// render settled. This way effects and memos only re-run when
		// the settled state actually differs from the previous one.
		hooks._pendingEffects = [];
		currentComponent._renderCallbacks = [];
		const settled = hooks._settled;
		hooks._list.forEach((hookItem, i) => {
			// Never touch state (useReducer/useState) or context hooks:
			// their current value is what the render loop settled on.
			if (hookItem._reducer || hookItem._context) return;
			hookItem._args = settled && settled[i]._args;
			hookItem._value = settled && settled[i]._value;
			hookItem._cleanup = settled && settled[i]._cleanup;
			hookItem._factory = settled && settled[i]._factory;
		});
	} else {
		hooks._pendingEffects.forEach(invokeCleanup);
		hooks._pendingEffects.forEach(invokeEffect);
		hooks._pendingEffects = [];
		// Snapshot the settled hook state before the render runs, so a
		// potential follow-up render in the same loop can restore it.
		hooks._settled = hooks._list.map(hookItem => ({
			_args: hookItem._args,
			_value: hookItem._value,
			_cleanup: hookItem._cleanup,
			_factory: hookItem._factory
		}));
	}
}
previousComponent = currentComponent;

